{"file_text": "@page "/chat"
@rendermode InteractiveServer
@using sv_6291f2e01e7448d19e1835f006f3bc21.Components.Chat
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(IsThreadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="_channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea Messages="_messages"
                 CurrentChannel="_currentChannel"
                 ThreadSummaries="_threadSummaries"
                 HasMoreMessages="_hasMoreMessages"
                 IsLoadingMore="_isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadMoreMessages" />

    @if (IsThreadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = new();
    private List<Message> _messages = new();
    private List<ThreadSummary> _threadSummaries = new();
    private Channel? _currentChannel;
    private int _activeChannelId;
    private bool _hasMoreMessages;
    private bool _isLoadingMore;
    private const int PageSize = 30;

    // Thread state
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = new();
    private bool IsThreadOpen => _threadRootMessage is not null;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _currentChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _hasMoreMessages = _messages.Count >= PageSize;
        _threadSummaries = BuildThreadSummaries(_messages);
        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (_isLoadingMore || _currentChannel is null) return;
        _isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messages.Count, PageSize);
        _hasMoreMessages = older.Count >= PageSize;
        _messages.InsertRange(0, older);
        _threadSummaries = BuildThreadSummaries(_messages);
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_currentChannel is null) return;
        var message = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        _messages.Add(message);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        if (_currentChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messages.Count);
        }
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is not null)
        {
            _threadReplies = await ChatService.GetThreadAsync(messageId);
        }
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
        // Update thread summary in main view
        _threadSummaries = BuildThreadSummaries(_messages, _threadRootMessage.Id, _threadReplies.Count);
    }

    private List<ThreadSummary> BuildThreadSummaries(List<Message> messages, int? updatedThreadId = null, int? updatedCount = null)
    {
        var rootIds = messages
            .Where(m => m.ReplyToId is null)
            .Select(m => m.Id)
            .ToHashSet();

        var summaries = messages
            .Where(m => m.ReplyToId is not null && rootIds.Contains(m.ReplyToId.Value))
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();

        if (updatedThreadId is not null && updatedCount is not null)
        {
            var existing = summaries.FindIndex(s => s.RootMessageId == updatedThreadId.Value);
            if (existing >= 0)
            {
                summaries[existing] = summaries[existing] with { ReplyCount = updatedCount.Value };
            }
            else
            {
                summaries.Add(new ThreadSummary(updatedThreadId.Value, updatedCount.Value, DateTime.Now));
            }
        }

        return summaries;
    }
}
