    color: #6c757d;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #e9ecef;
    color: #212529;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-bottom: 1px solid #dee2e6;
}

.thread-root-message .message-author {
    font-size: 0.85rem;
}

.thread-root-message .message-content {
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0.75rem 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.thread-reply {
    padding: 0.4rem 0;
}

.thread-reply .message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.thread-reply .message-author {
    font-size: 0.85rem;
}

.thread-reply .message-content {
    font-size: 0.85rem;
}
